import type { LLMProviderKey } from "../api/types";

/**
 * Static help for the "Conecta tu IA" step. Only fixed, hand-written text and URLs live
 * here: nothing generated by an LLM is ever rendered as a link (see lib/youtube.ts).
 */

export interface KeySource {
  provider: LLMProviderKey;
  /** Where the learner creates the key (the provider's own console). */
  url: string;
  /** Short, honest note about cost so nobody is surprised. */
  note: string;
}

